function whyClues(e,v){ const out=[]; const luce=['Poca luce','Luce media','Molta luce'][v.setup.luce], acq=['Poca acqua','Acqua media','Molta acqua'][v.setup.acqua]; const nm=Object.values(T.SPECIE).find(s=>e.text.indexOf(s.nome)===0); const sp=nm?v.sp.find(x=>x.nome===nm.nome):null;
  switch(e.kind){ case 'mutazione': out.push(v.R>.6?'Scariche frequenti':'Poche scariche',luce); if(nm) out.push('È una specie portata a cambiare'); break; case 'societa': out.push('Molte generazioni','Tanta esposizione',v.setup.oggetti.length?'Un oggetto ha dato un’idea':'Nessun oggetto: società semplice'); break; case 'cultura': out.push(v.setup.oggetti.length?'Un oggetto del vaso':'Nessun oggetto'); break; case 'guerra': out.push('Stesso cibo','Poco cibo'); break; case 'pace': out.push('Una moneta nel vaso'); break; case 'scisma': out.push('Due idee opposte e vicine'); break; case 'estinzione': out.push(luce,acq); if(sp&&sp.suit<.4) out.push('Non è il loro ambiente'); break; case 'mostro': out.push('Mutazione gigante','Tanto cibo'); break; case 'finale': out.push('Il vaso è stabile da un po’'); break; default: out.push(luce,acq); }
  return [...new Set(out)].slice(0,3); }
function guida(v){ const G=A.G, inb=A.inbox();
  if(v.finalePending&&G.ui.snoozeFinale<=A.todayIdx()) return {ic:'✨',t:'Il vaso ha trovato la sua strada',x:'Un finale ti aspetta.',b:'Scopri',a:'fin-open',c:'v'};
  if(v.pending.length) return {ic:'⚡',t:'Qualcosa sta succedendo',x:'Il tempo è sospeso finché non decidi.',b:'Guarda da vicino',a:'dec-open',c:'e'};
  if(inb.length) return {ic:'🔔',t:inb[0].title,x:inb[0].text,b:'Apri',a:'arr-open',c:'a'};
  const f=G.ui.fase==null?5:G.ui.fase; if(f===0) return {ic:'🧒',t:'Il barattolo è vuoto',x:'C’è solo il sasso, e batte. Ci vuole della terra.',b:'Metti la terra',a:'act',k:'terra',c:''}; if(f===1) return {ic:'🧒',t:'La terra è asciutta',x:'Non cresce niente senza acqua.',b:'Bagna la terra',a:'act',k:'acqua',c:''};
  if(G.req.kind==='notte'&&!G.req.done){ const nr=A.makeRequest(); if(nr.kind!=='notte') G.req=nr; else return {ic:f<3?'👣':'🌿',t:f<3?'Qualcuno sta arrivando':'Ora si aspetta',x:f<3?'Senti dei passi in giardino. Aspetta.':'Il vaso ha bisogno di tempo. Aspetta e guarda.',b:'Osserva il vaso',a:'osserva',c:'q'}; }
  if(!G.req.done){ const r=S.REQ[G.req.kind]; return G.req.kind==='osserva'?{ic:'🧒',t:'Ora tocca a te',x:r[0],b:r[1],a:'osserva',c:''}:{ic:'🧒',t:'Ora tocca a te',x:r[0],b:r[1],a:'act',k:G.req.kind,c:''}; }
  return {ic:'🙂',t:'Tutto tranquillo',x:'Tra poco avrai un’altra idea.',b:'Osserva il vaso',a:'osserva',c:'q',quiet:true}; }
